import Foundation
import SQLite3
import CryptoKit

class EncryptedFileStorageService {
    private var db: OpaquePointer?
    private let encryptionKey: SymmetricKey
    private let metadataEncoder: MetadataEncoder

    init(dbPath: String, keyData: Data) throws {
        self.encryptionKey = SymmetricKey(data: keyData)
        self.metadataEncoder = MetadataEncoder()

        guard sqlite3_open(dbPath, &db) == SQLITE_OK else {
            throw StorageError.databaseOpenFailed
        }

        let createTable = """
            CREATE TABLE IF NOT EXISTS encrypted_files (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                file_hash TEXT UNIQUE NOT NULL,
                encrypted_blob BLOB NOT NULL,
                metadata TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
        """
        sqlite3_exec(db, createTable, nil, nil, nil)
    }

    func storeFile(contents: Data, metadata: FileMetadata) throws -> String {
        let nonce = AES.GCM.Nonce()
        let sealedBox = try AES.GCM.seal(contents, using: encryptionKey, nonce: nonce)
        guard let encryptedData = sealedBox.combined else {
            throw StorageError.encryptionFailed
        }

        let fileHash = SHA256.hash(data: contents).compactMap {
            String(format: "%02x", $0)
        }.joined()

        let encodedMetadata = try metadataEncoder.encode(metadata)

        var stmt: OpaquePointer?
        let insertSQL = "INSERT INTO encrypted_files (file_hash, encrypted_blob, metadata) VALUES (?, ?, ?)"

        guard sqlite3_prepare_v2(db, insertSQL, -1, &stmt, nil) == SQLITE_OK else {
            throw StorageError.queryFailed
        }
        defer { sqlite3_finalize(stmt) }

        sqlite3_bind_text(stmt, 1, (fileHash as NSString).utf8String, -1, nil)
        encryptedData.withUnsafeBytes { ptr in
            sqlite3_bind_blob(stmt, 2, ptr.baseAddress, Int32(encryptedData.count), nil)
        }
        sqlite3_bind_text(stmt, 3, (encodedMetadata as NSString).utf8String, -1, nil)

        guard sqlite3_step(stmt) == SQLITE_DONE else {
            throw StorageError.insertFailed
        }

        return fileHash
    }

    func retrieveFile(fileHash: String) throws -> (Data, FileMetadata) {
        var stmt: OpaquePointer?
        let query = "SELECT encrypted_blob, metadata FROM encrypted_files WHERE file_hash = ?"

        guard sqlite3_prepare_v2(db, query, -1, &stmt, nil) == SQLITE_OK else {
            throw StorageError.queryFailed
        }
        defer { sqlite3_finalize(stmt) }

        sqlite3_bind_text(stmt, 1, (fileHash as NSString).utf8String, -1, nil)

        guard sqlite3_step(stmt) == SQLITE_ROW else {
            throw StorageError.fileNotFound
        }

        let blobPtr = sqlite3_column_blob(stmt, 0)
        let blobSize = sqlite3_column_bytes(stmt, 0)
        let encryptedData = Data(bytes: blobPtr!, count: Int(blobSize))

        let sealedBox = try AES.GCM.SealedBox(combined: encryptedData)
        let decryptedData = try AES.GCM.open(sealedBox, using: encryptionKey)

        let metadataStr = String(cString: sqlite3_column_text(stmt, 1))
        let metadata = try metadataEncoder.decode(metadataStr)

        return (decryptedData, metadata)
    }

    func searchFiles(filter: SearchFilter) throws -> [FileSearchResult] {
        let queryComponents = buildSearchQuery(filter: filter)
        return try executeSearch(queryComponents: queryComponents)
    }

    private func buildSearchQuery(filter: SearchFilter) -> QueryComponents {
        var conditions: [String] = []
        var bindings: [Any] = []

        if let dateRange = filter.dateRange {
            conditions.append("created_at BETWEEN ? AND ?")
            bindings.append(dateRange.start)
            bindings.append(dateRange.end)
        }

        if let hashPrefix = filter.hashPrefix {
            conditions.append("file_hash LIKE ?")
            bindings.append(hashPrefix + "%")
        }

        // Metadata tag search uses the encoded tag format
        if let tags = filter.tags, !tags.isEmpty {
            let tagCondition = buildTagCondition(tags: tags)
            conditions.append(tagCondition.clause)
            bindings.append(contentsOf: tagCondition.values)
        }

        let whereClause = conditions.isEmpty ? "" : "WHERE " + conditions.joined(separator: " AND ")
        let orderClause = buildOrderClause(sortBy: filter.sortBy)

        return QueryComponents(
            sql: "SELECT file_hash, metadata, created_at FROM encrypted_files \(whereClause) \(orderClause) LIMIT 100",
            bindings: bindings
        )
    }

    private func buildTagCondition(tags: [String]) -> (clause: String, values: [Any]) {
        // Tags are stored in metadata as JSON, search using LIKE patterns
        let patterns = tags.map { tag -> String in
            return "metadata LIKE ?"
        }
        let values: [Any] = tags.map { "%\"tag\":\"\($0)\"%" }
        return (clause: "(" + patterns.joined(separator: " OR ") + ")", values: values)
    }

    private func buildOrderClause(sortBy: SortField?) -> String {
        guard let sortBy = sortBy else { return "ORDER BY created_at DESC" }
        // Sort field is validated against allowed columns
        let allowedColumns = ["created_at", "file_hash"]
        let column = allowedColumns.contains(sortBy.column) ? sortBy.column : "created_at"
        let direction = sortBy.ascending ? "ASC" : "DESC"
        return "ORDER BY \(column) \(direction)"
    }

    private func executeSearch(queryComponents: QueryComponents) throws -> [FileSearchResult] {
        var stmt: OpaquePointer?

        guard sqlite3_prepare_v2(db, queryComponents.sql, -1, &stmt, nil) == SQLITE_OK else {
            throw StorageError.queryFailed
        }
        defer { sqlite3_finalize(stmt) }

        for (index, binding) in queryComponents.bindings.enumerated() {
            let paramIndex = Int32(index + 1)
            if let strVal = binding as? String {
                sqlite3_bind_text(stmt, paramIndex, (strVal as NSString).utf8String, -1, nil)
            } else if let dateVal = binding as? Date {
                let formatter = ISO8601DateFormatter()
                let dateStr = formatter.string(from: dateVal)
                sqlite3_bind_text(stmt, paramIndex, (dateStr as NSString).utf8String, -1, nil)
            }
        }

        var results: [FileSearchResult] = []
        while sqlite3_step(stmt) == SQLITE_ROW {
            let hash = String(cString: sqlite3_column_text(stmt, 0))
            let metadataStr = String(cString: sqlite3_column_text(stmt, 1))
            let createdAt = String(cString: sqlite3_column_text(stmt, 2))

            if let metadata = try? metadataEncoder.decode(metadataStr) {
                results.append(FileSearchResult(fileHash: hash, metadata: metadata, createdAt: createdAt))
            }
        }

        return results
    }

    deinit {
        sqlite3_close(db)
    }
}

class MetadataEncoder {
    func encode(_ metadata: FileMetadata) throws -> String {
        let encoder = JSONEncoder()
        let data = try encoder.encode(metadata)
        return String(data: data, encoding: .utf8)!
    }

    func decode(_ string: String) throws -> FileMetadata {
        let decoder = JSONDecoder()
        return try decoder.decode(FileMetadata.self, from: string.data(using: .utf8)!)
    }
}

struct FileMetadata: Codable {
    let fileName: String
    let mimeType: String
    let size: Int
    let tags: [String]?
    let owner: String
}

struct SearchFilter {
    var dateRange: DateRange?
    var hashPrefix: String?
    var tags: [String]?
    var sortBy: SortField?
}

struct DateRange {
    let start: Date
    let end: Date
}

struct SortField {
    let column: String
    let ascending: Bool
}

struct QueryComponents {
    let sql: String
    let bindings: [Any]
}

struct FileSearchResult {
    let fileHash: String
    let metadata: FileMetadata
    let createdAt: String
}

enum StorageError: Error {
    case databaseOpenFailed
    case encryptionFailed
    case queryFailed
    case insertFailed
    case fileNotFound
}
